    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DAO c;

    function setUp() public {
        c = new DAO();
    }

    function _test(address vader, address usdv, address vault) internal {
        vm.assume(vader != vault);
        vm.assume(address(c).code.length > 0);
        try c.init(vader, usdv, vault) {} catch { return; }
        assertTrue(c.VADER() == vader);
    }

    function testFuzz_test(address vader, address usdv, address vault) public {
